\begin{gather*}
						\text{If an object }A\text{ can be chosen in }m\text{ ways},\\
						\text{and an object }B\text{ can be chosen in }n\text{ ways},\\
						\text{such that no choice of }A\text{ coincides with no choice of }B,\\
						\text{then the choice of }A \text{ or }B\text{ can be made in } m+n \text{ ways}\\
						\end{gather*}

