formulas.latex:
\begin{gather*}
					\text{If an object }A\text{ can be chosen in }m\text{ ways},\\
					\text{and after each such choice,}\\
					\text{and an object }B\text{ can be chosen in }n\text{ ways},\\
					\text{then the choice of the pair}(A,B)\text{ can be made in } m\cdot n \text{ ways}\\
					\end{gather*}

